import './ui-icons.js';
import {saveReceipt} from './local-state.js';
import {flows,labels,requestNames} from './sector-config.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v==null?'Sob consulta':(v/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
let business=null;const modal=document.createElement('dialog');modal.id='sector-dialog';modal.className='sector-dialog';modal.setAttribute('aria-labelledby','sector-dialog-title');document.body.append(modal);
export function sectorActions(r){business=r;const types=(flows[r.sector]||flows.Outro);return `<div class="panel sector-actions"><h2>Seu próximo passo.</h2><p class="muted">${r.sector==='Gastronomia'?'Escolha sua mesa ou consulte o cardápio.':r.sector==='Automóveis'?'Conheça os veículos e combine uma visita.':r.sector==='Imobiliárias'?'Conheça os imóveis e solicite uma visita.':'Escolha como podemos ajudar.'}</p><div class="sector-actions-list">${types.map((type,i)=>`<button type="button" class="${i?'chip':'primary'}" data-request-type="${type}">${labels[type]} ↗</button>`).join('')}</div><p class="helper">Solicitações chegam ao negócio para confirmação. Datas, estoque e condições dependem da disponibilidade.</p><a data-business-whatsapp="${esc(r.id)}" class="text-link" href="https://wa.me/${encodeURIComponent(r.phone)}?text=${encodeURIComponent('Olá! Encontrei a empresa '+r.name+' na Helpu Local e gostaria de mais informações. Podem me ajudar?')}" target="_blank" rel="noopener">Conversar pelo WhatsApp ↗</a></div>`;}
export function sectorCatalog(r){business=r;if(!r.catalog?.length)return '';const heading=r.sector==='Gastronomia'?'Cardápio':r.sector==='Automóveis'?'Veículos disponíveis':r.sector==='Imobiliárias'?'Imóveis disponíveis':'Produtos e serviços';return `<section class="business-catalog sector-catalog" id="catalogo"><div class="section-head"><h2>${heading}</h2><span class="muted">${r.catalog.length} opções</span></div><div class="grid">${r.catalog.map(x=>`<article class="card">${x.image?`<img class="photo real-card-photo" src="${esc(x.image)}" alt="${esc(x.name)}" loading="lazy">`:'<div class="photo catalog-placeholder"><span>'+esc(x.brand||r.name)+'</span></div>'}<small>${esc(x.brand||r.sector)}</small><h3>${esc(x.name)}</h3><p>${esc([x.model,x.year,x.mileage?x.mileage+' km':''].filter(Boolean).join(' · ')||x.description)}</p><p class="price">${money(x.priceCents)}</p><button class="chip" data-item-detail="${esc(x.id)}" ${x.available?'':'disabled'}>${x.available?'Ver detalhes ↗':'Indisponível'}</button></article>`).join('')}</div><p class="helper">${r.sector==='Imobiliárias'?'Consulte a imobiliária sobre disponibilidade, visitas e condições de negociação.':'Preços de referência. O negócio confirma estoque, opções, frete e condições antes de concluir o pedido.'}</p></section>`;}
function openRequest(type,itemId='',eventId=''){if(!business)return;const r=business,event=r.events?.find(e=>e.id===eventId),items=(event?[]:r.catalog||[]).filter(x=>x.available),item=items.find(x=>x.id===itemId),product=['produto','pedido'].includes(type),scheduled=['reserva','visita','agendamento'].includes(type),people=['reserva','inscricao'].includes(type),today=new Date(Date.now()-3*3600000).toISOString().slice(0,10);if(product&&!item&&items.length){itemId=items[0].id;return openRequest(type,itemId);}modal.innerHTML=`<div class="request-heading"><div><span class="eyebrow">${esc(r.name)}</span><h2 id="sector-dialog-title">${labels[type]}</h2></div><button class="chip" data-request-close aria-label="Fechar solicitação">Fechar ×</button></div>${item?`<div class="request-product">${item.image?`<img src="${esc(item.image)}" alt="${esc(item.name)}">`:''}<div><h3>${esc(item.name)}</h3><p class="muted">${esc(item.description)}</p><p>${esc([item.brand,item.model,item.year,item.mileage?item.mileage+' km':'',item.transmission,item.fuel].filter(Boolean).join(' · '))}</p><strong>${money(item.priceCents)}</strong></div></div>`:''}${product&&!items.length?'<p>O negócio ainda está preparando o catálogo. Fale pelo WhatsApp para consultar as opções.</p><a class="primary" data-business-whatsapp="'+esc(r.id)+'" href="https://wa.me/'+encodeURIComponent(r.phone)+'?text='+encodeURIComponent('Olá! Encontrei a empresa '+r.name+' na Helpu Local e gostaria de conhecer as opções disponíveis. Podem me ajudar?')+'" target="_blank" rel="noopener">Consultar opções ↗</a>':`<form id="sector-request" data-type="${type}" data-event="${esc(eventId)}" data-key="${crypto.randomUUID()}">${event?`<div class="panel"><h3>${esc(event.name)}</h3><p>${esc(event.date.split('-').reverse().join('/'))} · ${esc(event.time)} · ${esc(event.venue)}</p><p>${event.priceCents===0?'Gratuito':money(event.priceCents)}</p><p class="local-lines">${esc(event.conditions)}</p></div>`:''}${items.length?`<label>${product?'Escolha o item':'Item de interesse · opcional'}<select name="itemId" data-request-item>${!product?'<option value="">Atendimento geral</option>':''}${items.map(x=>`<option value="${esc(x.id)}" ${x.id===itemId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`:''}${scheduled?`<div class="fields"><label>Data desejada<input name="date" type="date" min="${today}" required></label><label>Horário desejado<input name="time" type="time" required></label></div><p class="helper">Horário de Brasília. A empresa confirma a disponibilidade.</p>`:''}${people?'<label>Quantidade de pessoas<input name="people" type="number" min="1" max="50" value="2" required></label>':''}${product?`<div class="fields">${[['size',item.sizes,'Tamanho / opção'],['color',item.colors,'Cor']].filter(x=>x[1]?.length).map(([key,opts,label])=>`<label>${label}<select name="${key}" required><option value="">Selecione</option>${opts.map(v=>`<option>${esc(v)}</option>`).join('')}</select></label>`).join('')}<label>Quantidade<input name="quantity" type="number" min="1" max="100" value="1" required></label><label>Como deseja receber?<select name="fulfillment"><option>Retirada</option><option>Entrega</option>${r.sector==='Gastronomia'?'<option>No estabelecimento</option>':''}</select></label></div><label data-region hidden>Bairro ou região de entrega<input name="region" maxlength="200"></label>`:''}<div class="fields"><label>Seu nome<input name="name" minlength="2" maxlength="100" required autocomplete="name"></label><label>Seu WhatsApp com DDD<input name="phone" type="tel" maxlength="30" required autocomplete="tel"></label></div><label>${type==='orcamento'?'Descreva o que precisa':'Observações'+(['contato'].includes(type)?'':' · opcional')}<textarea name="message" maxlength="2000" ${['orcamento','contato'].includes(type)?'required minlength="3"':''} rows="3"></textarea></label><div hidden><input name="website" tabindex="-1" autocomplete="off"></div><label class="consent"><input type="checkbox" name="consent" required> Autorizo ${esc(r.name)} a responder a esta solicitação pelo WhatsApp.</label><p class="helper">${scheduled?'O envio não confirma a reserva ou o horário. ':''}A empresa dará retorno para combinar os detalhes. Nenhum pagamento é cobrado aqui. <a href="/privacidade.html" target="_blank" rel="noopener">Privacidade ↗</a></p><p role="alert"></p><button type="submit" class="primary">${labels[type]}</button></form>`}`;if(!modal.open)modal.showModal();modal.scrollTop=0;}
document.addEventListener('click',e=>{const action=e.target.closest('[data-request-type]'),itemButton=e.target.closest('[data-item-detail]');if(action)openRequest(action.dataset.requestType,'',action.dataset.eventId||'');if(itemButton){const type=business.sector==='Gastronomia'?'pedido':business.sector==='Automóveis'?'visita':['Compras','Moda'].includes(business.sector)?'produto':(flows[business.sector]||flows.Outro)[0];openRequest(type,itemButton.dataset.itemDetail);}if(e.target.closest('[data-request-close]'))modal.close();});
document.addEventListener('change',e=>{if(e.target.matches('[name=fulfillment]')&&e.target.closest('#sector-request')){const region=modal.querySelector('[data-region]');region.hidden=e.target.value!=='Entrega';region.querySelector('input').required=!region.hidden;}if(e.target.matches('[data-request-item]')){const form=e.target.closest('form'),values=Object.fromEntries(new FormData(form));openRequest(form.dataset.type,e.target.value);const next=modal.querySelector('form');for(const key of ['name','phone','message','date','time','people','quantity'])if(next?.elements[key]&&values[key])next.elements[key].value=values[key];}});
window.addEventListener('hashchange',()=>{modal.close();business=null;});
document.addEventListener('submit',async e=>{if(e.target.id!=='sector-request')return;e.preventDefault();const f=e.target,b=f.querySelector('[type=submit]'),r=business,values=Object.fromEntries(new FormData(f));b.disabled=true;try{const response=await fetch('/api/local/lead',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...values,type:f.dataset.type,eventId:f.dataset.event,businessId:r.id,requestKey:f.dataset.key,consent:f.elements.consent.checked})}),d=await response.json();if(!response.ok)throw Error(d.error||'Não foi possível enviar.');if(d.preview){f.innerHTML='<div class="request-success"><h3>Prévia concluída.</h3><p>Você está no modo administrativo. Nenhuma solicitação foi registrada ou enviada ao negócio.</p></div>';return;}saveReceipt({id:f.dataset.key,businessId:r.id,businessName:r.name,label:requestNames[f.dataset.type]||'Contato',at:Date.now()});const message='Olá! Enviei uma solicitação pela Helpu Local. Meu nome é '+values.name+'.\n'+d.summary;f.innerHTML=`<div class="request-success"><h3>Solicitação registrada.</h3><p>${esc(requestNames[f.dataset.type])} recebida para análise. Aguarde a confirmação do negócio.</p><a class="primary" data-business-whatsapp="${esc(r.id)}" href="https://wa.me/${encodeURIComponent(r.phone)}?text=${encodeURIComponent(message)}" target="_blank" rel="noopener">Continuar no WhatsApp ↗</a></div>`;}catch(err){f.querySelector('[role=alert]').textContent=err.message;b.disabled=false;}});
